#!/usr/bin/env node
// TEST FİKSTÜRÜ — gerçek Codex değildir. npm global kurulumunun codex.js giriş noktasını taklit eder:
// aldığı argümanları ve stdin'i (UTF-8) JSON olarak geri yazar; shell yorumlaması olmadığını kanıtlamak için.
const chunks = [];
process.stdin.on("data", (c) => chunks.push(c));
process.stdin.on("end", () => {
  process.stdout.write(JSON.stringify({ argv: process.argv.slice(2), stdin: Buffer.concat(chunks).toString("utf8") }));
});
